old='''function arcadeCanvas(label){
 const wrap=document.createElement("div");wrap.className="arcade-wrap";const c=document.createElement("canvas");c.className="arcade-canvas";c.width=360;c.height=220;c.setAttribute("aria-label",label);wrap.appendChild(c);els.playArea.appendChild(wrap);return c;
}'''
new='''function arcadeCanvas(label){
 const wrap=document.createElement("div");wrap.className="arcade-wrap";const c=document.createElement("canvas");c.className="arcade-canvas";const dpr=Math.min(3,Math.max(1,window.devicePixelRatio||1));c.width=Math.round(360*dpr);c.height=Math.round(220*dpr);c.dataset.logicalW="360";c.dataset.logicalH="220";c.setAttribute("aria-label",label);wrap.appendChild(c);els.playArea.appendChild(wrap);const ctx=c.getContext("2d");ctx.setTransform(dpr,0,0,dpr,0,0);ctx.imageSmoothingEnabled=true;ctx.imageSmoothingQuality="high";return c;
}
function arcadeControlDeck(kind="slide",label="CONTROL"){
 const deck=document.createElement("div");deck.className=`arcade-control-deck ${kind}`;const pad=document.createElement("div");pad.className="arcade-trackpad";pad.setAttribute("role","slider");pad.setAttribute("aria-label",label);pad.innerHTML='<span class="control-arrow">‹</span><b class="control-thumb">↔</b><span class="control-arrow">›</span>';deck.appendChild(pad);let button=null;if(kind==="move-fire"){button=document.createElement("button");button.className="arcade-fire-btn";button.type="button";button.textContent="●";button.setAttribute("aria-label",tr("DISPARAR","FIRE","TIRER"));deck.appendChild(button)}els.playArea.appendChild(deck);return{deck,pad,button};
}
function bindRelativePad(pad,onMove){
 let active=false,lastX=0;const thumb=pad.querySelector(".control-thumb");const down=e=>{active=true;lastX=e.clientX;pad.classList.add("active");try{pad.setPointerCapture(e.pointerId)}catch{}};const move=e=>{if(!active)return;const r=pad.getBoundingClientRect(),dx=e.clientX-lastX;lastX=e.clientX;onMove(dx*360/Math.max(1,r.width));const pct=Math.max(-42,Math.min(42,(e.clientX-r.left)/r.width*84-42));if(thumb)thumb.style.transform=`translateX(${pct}px)`};const up=()=>{active=false;pad.classList.remove("active");if(thumb)thumb.style.transform="translateX(0)"};pad.addEventListener("pointerdown",down);pad.addEventListener("pointermove",move);pad.addEventListener("pointerup",up);pad.addEventListener("pointercancel",up);
}
function drawArcadeBackdrop(ctx,kind,ts=0){
 ctx.save();const g=ctx.createLinearGradient(0,0,0,220);if(kind==="space"){g.addColorStop(0,"#07122f");g.addColorStop(1,"#172c67")}else if(kind==="terrace"){g.addColorStop(0,"#78d7ff");g.addColorStop(.58,"#d9f2ff");g.addColorStop(1,"#f8d797")}else if(kind==="road"){g.addColorStop(0,"#97d9ff");g.addColorStop(.55,"#d8eeff");g.addColorStop(1,"#595b6f")}else{g.addColorStop(0,"#0b1641");g.addColorStop(1,"#28195d")}ctx.fillStyle=g;ctx.fillRect(0,0,360,220);if(kind==="space"||kind==="night"){for(let i=0;i<34;i++){const x=(i*83+17)%360,y=(i*47+11)%200;ctx.globalAlpha=.35+((i%4)*.15);ctx.fillStyle=i%7===0?"#ffd85c":"#fff";ctx.beginPath();ctx.arc(x,y,(i%5===0?1.7:1),0,7);ctx.fill()}ctx.globalAlpha=1}if(kind==="space"){ctx.globalAlpha=.28;ctx.fillStyle="#7d62ff";ctx.beginPath();ctx.arc(35,190,60,Math.PI,0);ctx.fill();ctx.fillStyle="#3ac8ff";ctx.beginPath();ctx.arc(330,215,74,Math.PI,0);ctx.fill();ctx.globalAlpha=1}if(kind==="terrace"){ctx.globalAlpha=.5;ctx.fillStyle="#7fc768";ctx.beginPath();ctx.moveTo(0,150);ctx.lineTo(70,95);ctx.lineTo(130,145);ctx.lineTo(220,80);ctx.lineTo(360,148);ctx.lineTo(360,220);ctx.lineTo(0,220);ctx.fill();ctx.globalAlpha=.75;ctx.fillStyle="#67c7e8";ctx.fillRect(0,158,360,62);ctx.globalAlpha=1;ctx.fillStyle="#f4ead9";ctx.fillRect(0,190,360,30)}if(kind==="road"){ctx.fillStyle="#555968";ctx.beginPath();ctx.moveTo(115,220);ctx.lineTo(158,70);ctx.lineTo(202,70);ctx.lineTo(245,220);ctx.fill()}ctx.restore();
}'''
assert old in s
s=s.replace(old,new)
s=s.replace('function canvasPointerX(e,c){const r=c.getBoundingClientRect();return Math.max(0,Math.min(c.width,(e.clientX-r.left)*c.width/r.width))}','function canvasPointerX(e,c){const r=c.getBoundingClientRect();return Math.max(0,Math.min(360,(e.clientX-r.left)*360/r.width))}')
s=s.replace('function canvasPointerY(e,c){const r=c.getBoundingClientRect();return Math.max(0,Math.min(c.height,(e.clientY-r.top)*c.height/r.height))}','function canvasPointerY(e,c){const r=c.getBoundingClientRect();return Math.max(0,Math.min(220,(e.clientY-r.top)*220/r.height))}')
s=s.replace('const swing=Math.sin(t*.006)*9;','const swing=Math.sin(t*.0055)*8;')

