css=r'''
/* v4.2 FINAL — approved art direction + finger-safe controls */
html,body{height:100%;max-height:100dvh;overflow:hidden}body{min-height:100dvh;overscroll-behavior:none;background:radial-gradient(circle at 12% 4%,rgba(95,69,255,.12),transparent 26%),radial-gradient(circle at 88% 12%,rgba(50,183,255,.12),transparent 25%),linear-gradient(180deg,#f9faff,#f7f4ee)}.shell{height:100dvh;min-height:0;max-height:100dvh;overflow:hidden;padding:max(9px,env(safe-area-inset-top)) 11px max(8px,env(safe-area-inset-bottom));gap:7px}.logo b{background:linear-gradient(145deg,#8059ff,#5a36f2 65%,#3d24c9);box-shadow:0 5px 0 #2d1b94,0 10px 22px rgba(86,62,240,.24)}.game-card{min-height:0!important;flex:1;padding:12px 13px 10px}.challenge{margin:8px 0 3px}.challenge h1{font-size:clamp(25px,7.3vw,34px);line-height:1.01}.challenge p{font-size:clamp(13px,3.7vw,16px);font-weight:760;color:#55566e}.play-area{min-height:0;flex:1;margin:4px -2px 0;padding:5px 0}.mascot-zone{min-height:118px}.stickman{max-height:140px}
body.arcade-level .game-card{min-height:0!important}body.arcade-level .play-area{min-height:0;display:flex;flex-direction:column;justify-content:center;gap:8px;padding:3px 0 0;margin-top:2px;background:transparent;border:0}body.arcade-level .mascot-zone{display:none}.arcade-wrap{width:min(100%,430px);height:auto!important;aspect-ratio:360/220;border:2px solid rgba(14,18,48,.92);border-radius:24px;overflow:hidden;background:#101738;box-shadow:0 11px 0 rgba(31,34,78,.10),0 18px 34px rgba(34,44,110,.17);touch-action:none}.arcade-canvas{display:block;width:100%;height:100%!important;background:transparent;touch-action:none}.arcade-control-deck{width:min(100%,430px);min-height:76px;border:2px solid rgba(29,31,75,.25);border-radius:23px;padding:9px;background:linear-gradient(180deg,#fff,#f5f7ff);box-shadow:0 7px 18px rgba(28,34,88,.10);display:grid;grid-template-columns:1fr;gap:8px;align-items:center;touch-action:none;user-select:none}.arcade-control-deck.move-fire{grid-template-columns:minmax(0,1fr) 78px}.arcade-trackpad{position:relative;height:56px;border-radius:999px;border:1.5px solid rgba(62,66,140,.18);background:linear-gradient(90deg,rgba(204,105,255,.25),rgba(91,70,255,.18) 50%,rgba(43,189,255,.27));display:flex;align-items:center;justify-content:space-between;padding:0 17px;touch-action:none;overflow:hidden}.arcade-trackpad::before{content:"DESLIZA AQUÍ";position:absolute;left:50%;top:5px;transform:translateX(-50%);font-size:8px;font-weight:1000;letter-spacing:1.1px;color:rgba(43,45,97,.54)}.control-arrow{font-size:28px;font-weight:1000;color:#5e56aa}.control-thumb{display:grid;place-items:center;width:44px;height:44px;border-radius:50%;background:linear-gradient(145deg,#7559ff,#405ee8);color:#fff;border:3px solid #fff;box-shadow:0 5px 0 #30399b;font-size:22px;transition:transform .08s linear}.arcade-fire-btn{height:58px;border:0;border-radius:20px;background:linear-gradient(145deg,#ff4d79,#ff315c 65%,#d70f40);color:#fff;font-size:29px;font-weight:1000;box-shadow:0 6px 0 #9e1839}.stickman.sprite-panic{animation-duration:.34s!important}.stickman.sprite-nervous{animation-duration:.72s!important}.stickman.sprite-dance{animation-duration:1.2s!important}.stickman.sprite-win{animation-duration:.68s!important}footer{flex:none;font-size:8px;padding:0 2px}
@media(max-height:760px){.shell{gap:5px}.topbar{transform:scale(.94);transform-origin:center top;margin-bottom:-4px}.game-card{padding:9px 11px 8px}.challenge h1{font-size:clamp(23px,6.8vw,30px)}.challenge p{font-size:13px}.mascot-zone{min-height:92px}.stickman{height:110px}.arcade-wrap{max-height:28dvh;width:auto;max-width:100%;align-self:center}.arcade-control-deck{min-height:64px;padding:6px}.arcade-trackpad{height:48px}.control-thumb{width:38px;height:38px}.arcade-fire-btn{height:50px}}
@media(max-height:660px){.challenge h1{font-size:22px}.challenge p{font-size:12px}.checkpoint-text{display:none}.arcade-wrap{max-height:25dvh}.arcade-control-deck{min-height:58px}.arcade-trackpad{height:43px}.arcade-trackpad::before{display:none}.control-thumb{width:34px;height:34px;font-size:18px}.arcade-fire-btn{height:45px}footer{display:none}}
'''
